data.gde_tour:
{
    name: "DemoGuideOrder",
    condition: {
        // Launched from the main list only
        context: "list",
        inst: "the_ajax_DemoOrder",
        // Needs create+upate rights to get this guide
        access: function(ctn) {
            // already in DEMO_USER rights, but just in case
            return $grant.accessCreate("DemoOrder") && $grant.accessUpdate("DemoOrder");
        },
        // Init tour when launched
        init: function(ctn, tour) {
            let def = this;
            console.log(`Play guide ${def.name} from ${def.launcher.attr("id")}`);
            // Create button exists ?
            let btn = $(".objlist.object-DemoOrder button[data-action='create']", ctn);
            if (!btn.length) {
                $app.alert($T("ACCESS_DENIED"));
                return null; // stop playing
            }
            return true; // ready to go
            // return false = wait for someting to be loaded/ready, init will be called later
        }
    },
    steps: [{
        step: "welcome",
        title: {
            FRA: "Bienvenue !",
            ENU: "Let's go create your order!"
        },
        info: {
            FRA: "Ce guide vous aide à utiliser le formulaire de création de commande",
            ENU: "This guide helps you use the order creation form"
        }
    }, {
        step: "create",
        title: {
            FRA: "Créer depuis la liste",
            ENU: "Create from the list"
        },
        info: {
            FRA: "Cliquer sur le bouton de création pour accéder au formulaire de saisie",
            ENU: "Click on the create button to open the create form"
        },
        attach: {
            pos: "bottom",
            align: "center",
            sel: ".objlist.object-DemoOrder button[data-action='create']"
        },
        next: {
            event: "click" // Simple click
        }
    }, {
        step: "client",
        title: {
            FRA: "Sélectionnez un client",
            ENU: "Select a client"
        },
        info: {
            FRA: "Ouvrir la fenêtre de recherche d'un client",
            ENU: "Open the reference picker to select the client"
        },
        attach: {
            pos: "right",
            align: "bottom",
            sel: "button.refsel_field_demoOrdCliId__demoCliCode"
        },
        next: {
            event: "onload" // Click on lookup and wait for dialog
        }
    }, {
        step: "pick-client",
        title: {
            FRA: "Cliquez sur une ligne pour choisir un client",
            ENU: "Click on a row to select the client"
        },
        attach: {
            pos: "bottom",
            align: "center", // right, left
            sel: "#list_DemoClient_ref_ajax_DemoClient tr[data-rowid='2']"
        },
        next: {
            event: "onload" // Click on row and wait for parent populate
        }
    }, {
        step: "product",
        title: {
            FRA: "Choisir un produit",
            ENU: "Select one product"
        },
        attach: {
            pos: "right",
            align: "center",
            sel: "button.refsel_field_demoOrdPrdId__demoPrdReference"
        },
        next: {
            condition: function(ctn, obj, tour) {
                let step = this;
                // wait for the populate from ref picker to set the parent input
                return $("#field_demoOrdPrdId__demoPrdReference", ctn).val() != "";
            }
        }
    }, {
        step: "quantity",
        title: {
            FRA: "Choisir une quantité",
            ENU: "Choose a quantity"
        },
        attach: {
            pos: "bottom",
            sel: "#field_demoOrdQuantity"
        },
        next: {
            event: "change", // on input change
            condition: function(ctn, obj, tour) {
                // until quantity is equals to 0
                let v = $("#field_demoOrdQuantity", ctn).val();
                if (!v || v < 1) {
                    $('.guide-tooltip .step-desc').text($T("ERR_DEMO_ORD_QUANTITY"));
                    return false; // wait for a correct value
                }
                return true; // ok go next
            }
        }
    }, {
        step: "save",
        title: {
            FRA: "Cliquez pour enregistrer cette commande",
            ENU: "Click to save this order"
        },
        attach: {
            pos: "left",
            sel: "button[data-action='save']"
        },
        next: {
            condition: (ctn) => {
                // Wait for the validate button after reload
                return $("button[data-action='DEMO_ORD_STATUS-VALIDATE']", ctn).length > 0;
            }
        }
    }, {
        step: "validate",
        title: {
            FRA: "Validez la commande",
            ENU: "Validate the order"
        },
        info: {
            FRA: "Vous pouvez changer d'étape en cliquant sur les boutons de transition d'état.",
            ENU: "You can change steps by clicking the state transition buttons."
        },
        attach: {
            pos: "bottom",
            sel: "button[data-action='DEMO_ORD_STATUS-VALIDATE']"
        },
        next: {
            event: "onload" // click + wait for ajax update
        }
    }, {
        step: "status",
        title: {
            FRA: "La barre d'état vous permet de voir la progression de la commande.",
            ENU: "The status bar allows you to see the progress of the order."
        },
        attach: {
            pos: "bottom",
            align: "right",
            sel: ".navbar-metro-line"
        }
    }],
    exitToast: {
        FRA: "Merci et à bientôt !",
        ENU: "Thank you and see you soon!"
    }
}
